SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('SchemaMigrations') IS NULL CREATE TABLE SchemaMigrations (version int NOT NULL PRIMARY KEY, appliedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('Users') IS NULL BEGIN
CREATE TABLE Users (id uniqueidentifier PRIMARY KEY, email nvarchar(254) NOT NULL UNIQUE, passwordHash nvarchar(255) NOT NULL, name nvarchar(120) NOT NULL, role nvarchar(30) NOT NULL DEFAULT 'customer', verified bit NOT NULL DEFAULT 0, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Sessions (tokenHash char(64) PRIMARY KEY, userId uniqueidentifier NOT NULL REFERENCES Users(id), csrf nvarchar(80) NOT NULL, expiresAt datetime2 NOT NULL);
CREATE TABLE AccessTokens (id uniqueidentifier PRIMARY KEY, tokenHash char(64) NOT NULL UNIQUE, purpose nvarchar(40) NOT NULL, email nvarchar(254), resourceId uniqueidentifier, data nvarchar(max), expiresAt datetime2 NOT NULL, usedAt datetime2);
CREATE TABLE Vendors (id uniqueidentifier PRIMARY KEY, ownerId uniqueidentifier NOT NULL REFERENCES Users(id), name nvarchar(120) NOT NULL, slug nvarchar(80) NOT NULL UNIQUE, status nvarchar(30) NOT NULL DEFAULT 'draft', trusted bit NOT NULL DEFAULT 0, paymentEligible bit NOT NULL DEFAULT 0, country char(2), category nvarchar(60), description nvarchar(2000), feedback nvarchar(2000), data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Vendor_Status CHECK (status IN ('draft','pending_review','changes_requested','approved','rejected','suspended')));
CREATE TABLE VendorMembers (vendorId uniqueidentifier REFERENCES Vendors(id), userId uniqueidentifier REFERENCES Users(id), role nvarchar(30) NOT NULL, PRIMARY KEY(vendorId,userId));
CREATE TABLE VendorApplications (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), state nvarchar(30) NOT NULL, feedback nvarchar(2000), actorId uniqueidentifier REFERENCES Users(id), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE PolicyAcceptances (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), userId uniqueidentifier NOT NULL REFERENCES Users(id), version nvarchar(30) NOT NULL, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(vendorId,userId,version));
CREATE TABLE StoreThemes (vendorId uniqueidentifier PRIMARY KEY REFERENCES Vendors(id), draft nvarchar(max) NOT NULL DEFAULT '{}', published nvarchar(max) NOT NULL DEFAULT '{}', updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE StoreDomains (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), hostname nvarchar(253) NOT NULL UNIQUE, challenge nvarchar(120) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'requested', verifiedAt datetime2, tlsVerifiedAt datetime2, checkedAt datetime2, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Categories (slug nvarchar(60) PRIMARY KEY, name nvarchar(80) NOT NULL, image nvarchar(1000));
CREATE TABLE Collections (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier REFERENCES Vendors(id), name nvarchar(120) NOT NULL, data nvarchar(max) NOT NULL DEFAULT '{}');
CREATE TABLE Products (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), name nvarchar(180) NOT NULL, description nvarchar(max) NOT NULL DEFAULT '', category nvarchar(60) NOT NULL REFERENCES Categories(slug), currency char(3) NOT NULL, status nvarchar(30) NOT NULL DEFAULT 'draft', image nvarchar(1000), data nvarchar(max) NOT NULL DEFAULT '{}', version rowversion, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT CK_Product_Status CHECK (status IN ('draft','pending_review','published','archived')));
CREATE TABLE ProductVariants (id uniqueidentifier PRIMARY KEY, productId uniqueidentifier NOT NULL REFERENCES Products(id), sku nvarchar(100) NOT NULL UNIQUE, label nvarchar(120) NOT NULL DEFAULT 'Default', price decimal(19,4) NOT NULL, regularPrice decimal(19,4), stock int NOT NULL DEFAULT 0, reserved int NOT NULL DEFAULT 0, image nvarchar(1000), version rowversion, CONSTRAINT CK_Stock CHECK (stock>=0 AND reserved>=0 AND reserved<=stock), CONSTRAINT CK_Price CHECK(price>=0));
CREATE TABLE ProductMedia (id uniqueidentifier PRIMARY KEY, productId uniqueidentifier REFERENCES Products(id), vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), path nvarchar(500) NOT NULL, alt nvarchar(200) NOT NULL, width int NOT NULL, height int NOT NULL);
CREATE TABLE ModerationHistory (id uniqueidentifier PRIMARY KEY, productId uniqueidentifier NOT NULL REFERENCES Products(id), actorId uniqueidentifier REFERENCES Users(id), state nvarchar(30) NOT NULL, reason nvarchar(2000), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Carts (id uniqueidentifier PRIMARY KEY, userId uniqueidentifier REFERENCES Users(id), consent bit NOT NULL DEFAULT 0, email nvarchar(254), updatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE CartItems (cartId uniqueidentifier REFERENCES Carts(id), variantId uniqueidentifier REFERENCES ProductVariants(id), quantity int NOT NULL CHECK(quantity>0 AND quantity<=99), PRIMARY KEY(cartId,variantId));
CREATE TABLE CommissionRules (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier REFERENCES Vendors(id), category nvarchar(60), bps int NOT NULL CHECK(bps>=0 AND bps<=10000), version int NOT NULL, active bit NOT NULL DEFAULT 1, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Coupons (code nvarchar(40) PRIMARY KEY, bps int NOT NULL CHECK(bps>0 AND bps<=10000), vendorId uniqueidentifier REFERENCES Vendors(id), active bit NOT NULL DEFAULT 1, startsAt datetime2, endsAt datetime2, maxUses int, used int NOT NULL DEFAULT 0);
CREATE TABLE Orders (id uniqueidentifier PRIMARY KEY, cartId uniqueidentifier REFERENCES Carts(id), userId uniqueidentifier REFERENCES Users(id), idempotencyKey nvarchar(100) NOT NULL UNIQUE, requestHash char(64) NOT NULL, currency char(3) NOT NULL, total decimal(19,4) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'pending', paymentState nvarchar(30) NOT NULL DEFAULT 'pending', provider nvarchar(30) NOT NULL, address nvarchar(max) NOT NULL, snapshot nvarchar(max) NOT NULL, accessHash char(64) NOT NULL, accessExpiresAt datetime2 NOT NULL, expiresAt datetime2 NOT NULL, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE VendorOrders (id uniqueidentifier PRIMARY KEY, orderId uniqueidentifier NOT NULL REFERENCES Orders(id), vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), currency char(3) NOT NULL, total decimal(19,4) NOT NULL, commission decimal(19,4) NOT NULL, paymentState nvarchar(30) NOT NULL DEFAULT 'pending', fulfillmentState nvarchar(30) NOT NULL DEFAULT 'unfulfilled', snapshot nvarchar(max) NOT NULL, UNIQUE(orderId,vendorId));
CREATE TABLE OrderItems (id uniqueidentifier PRIMARY KEY, orderId uniqueidentifier NOT NULL REFERENCES Orders(id), vendorOrderId uniqueidentifier NOT NULL REFERENCES VendorOrders(id), variantId uniqueidentifier NOT NULL REFERENCES ProductVariants(id), quantity int NOT NULL, refundedQuantity int NOT NULL DEFAULT 0, unitPrice decimal(19,4) NOT NULL, discount decimal(19,4) NOT NULL, tax decimal(19,4) NOT NULL, commission decimal(19,4) NOT NULL, snapshot nvarchar(max) NOT NULL);
CREATE TABLE InventoryReservations (id uniqueidentifier PRIMARY KEY, orderId uniqueidentifier NOT NULL REFERENCES Orders(id), variantId uniqueidentifier NOT NULL REFERENCES ProductVariants(id), quantity int NOT NULL, state nvarchar(20) NOT NULL DEFAULT 'reserved', expiresAt datetime2 NOT NULL, UNIQUE(orderId,variantId));
CREATE TABLE InventoryMovements (id uniqueidentifier PRIMARY KEY, variantId uniqueidentifier NOT NULL REFERENCES ProductVariants(id), quantity int NOT NULL, reason nvarchar(80) NOT NULL, source nvarchar(180) NOT NULL UNIQUE, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE PaymentAttempts (id uniqueidentifier PRIMARY KEY, orderId uniqueidentifier NOT NULL REFERENCES Orders(id), provider nvarchar(30) NOT NULL, providerId nvarchar(200), state nvarchar(30) NOT NULL DEFAULT 'created', data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE PaymentTransactions (id uniqueidentifier PRIMARY KEY, orderId uniqueidentifier NOT NULL REFERENCES Orders(id), vendorOrderId uniqueidentifier REFERENCES VendorOrders(id), provider nvarchar(30) NOT NULL, externalId nvarchar(200) NOT NULL, kind nvarchar(30) NOT NULL, currency char(3) NOT NULL, amount decimal(19,4) NOT NULL, state nvarchar(30) NOT NULL, data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(provider,externalId,kind));
CREATE TABLE ProviderAccounts (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), provider nvarchar(30) NOT NULL, externalId nvarchar(200) NOT NULL, chargesEnabled bit NOT NULL DEFAULT 0, payoutsEnabled bit NOT NULL DEFAULT 0, data nvarchar(max) NOT NULL DEFAULT '{}', UNIQUE(vendorId,provider));
CREATE TABLE WebhookEvents (id uniqueidentifier PRIMARY KEY, provider nvarchar(30) NOT NULL, externalId nvarchar(200) NOT NULL, data nvarchar(max) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, nextAttemptAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), error nvarchar(500), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(provider,externalId));
CREATE TABLE LedgerEntries (id uniqueidentifier PRIMARY KEY, journalId uniqueidentifier NOT NULL, vendorId uniqueidentifier REFERENCES Vendors(id), orderId uniqueidentifier REFERENCES Orders(id), account nvarchar(50) NOT NULL, currency char(3) NOT NULL, amount decimal(19,4) NOT NULL, source nvarchar(200) NOT NULL, reversalOf uniqueidentifier REFERENCES LedgerEntries(id), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(source,account));
CREATE TABLE Transfers (id uniqueidentifier PRIMARY KEY, vendorOrderId uniqueidentifier NOT NULL REFERENCES VendorOrders(id), provider nvarchar(30) NOT NULL, externalId nvarchar(200), amount decimal(19,4) NOT NULL, currency char(3) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'pending', data nvarchar(max) NOT NULL DEFAULT '{}', UNIQUE(vendorOrderId,provider));
CREATE TABLE Payouts (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), provider nvarchar(30) NOT NULL, externalId nvarchar(200) NOT NULL, currency char(3) NOT NULL, amount decimal(19,4) NOT NULL, state nvarchar(30) NOT NULL, data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(provider,externalId));
CREATE TABLE Returns (id uniqueidentifier PRIMARY KEY, orderItemId uniqueidentifier NOT NULL REFERENCES OrderItems(id), orderId uniqueidentifier NOT NULL REFERENCES Orders(id), vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), quantity int NOT NULL, reason nvarchar(2000) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'requested', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Refunds (id uniqueidentifier PRIMARY KEY, returnId uniqueidentifier NOT NULL UNIQUE REFERENCES Returns(id), orderId uniqueidentifier NOT NULL REFERENCES Orders(id), vendorOrderId uniqueidentifier NOT NULL REFERENCES VendorOrders(id), providerId nvarchar(200), currency char(3) NOT NULL, amount decimal(19,4) NOT NULL, commission decimal(19,4) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'pending', data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Shipments (id uniqueidentifier PRIMARY KEY, vendorOrderId uniqueidentifier NOT NULL REFERENCES VendorOrders(id), carrier nvarchar(100), tracking nvarchar(200), state nvarchar(30) NOT NULL, data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Reviews (id uniqueidentifier PRIMARY KEY, productId uniqueidentifier NOT NULL REFERENCES Products(id), orderItemId uniqueidentifier NOT NULL UNIQUE REFERENCES OrderItems(id), name nvarchar(120) NOT NULL, rating int NOT NULL CHECK(rating>=1 AND rating<=5), body nvarchar(2000) NOT NULL, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Wishlists (userId uniqueidentifier REFERENCES Users(id), productId uniqueidentifier REFERENCES Products(id), PRIMARY KEY(userId,productId));
CREATE TABLE Banners (id uniqueidentifier PRIMARY KEY, title nvarchar(180) NOT NULL, image nvarchar(1000), mobileImage nvarchar(1000), alt nvarchar(200) NOT NULL, href nvarchar(500) NOT NULL, startsAt datetime2, endsAt datetime2, active bit NOT NULL DEFAULT 1);
CREATE TABLE AuditEvents (id uniqueidentifier PRIMARY KEY, actorId uniqueidentifier REFERENCES Users(id), vendorId uniqueidentifier REFERENCES Vendors(id), action nvarchar(100) NOT NULL, resourceId nvarchar(100), data nvarchar(max) NOT NULL DEFAULT '{}', createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE OutboxMessages (id uniqueidentifier PRIMARY KEY, type nvarchar(50) NOT NULL, source nvarchar(200) NOT NULL UNIQUE, data nvarchar(max) NOT NULL, state nvarchar(20) NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, nextAttemptAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), lockedAt datetime2, lastError nvarchar(500), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE ImportJobs (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), hash char(64) NOT NULL, state nvarchar(20) NOT NULL DEFAULT 'preview', data nvarchar(max) NOT NULL, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), UNIQUE(vendorId,hash));
CREATE TABLE Subscriptions (id uniqueidentifier PRIMARY KEY, vendorId uniqueidentifier NOT NULL REFERENCES Vendors(id), providerId nvarchar(200) UNIQUE, [plan] nvarchar(40) NOT NULL, state nvarchar(30) NOT NULL DEFAULT 'inactive', endsAt datetime2, data nvarchar(max) NOT NULL DEFAULT '{}');
CREATE TABLE PromotedPlacements (id uniqueidentifier PRIMARY KEY, productId uniqueidentifier NOT NULL REFERENCES Products(id), startsAt datetime2 NOT NULL, endsAt datetime2 NOT NULL, active bit NOT NULL DEFAULT 1);
CREATE TABLE LoyaltyTransactions (id uniqueidentifier PRIMARY KEY, userId uniqueidentifier NOT NULL REFERENCES Users(id), orderId uniqueidentifier REFERENCES Orders(id), points int NOT NULL, source nvarchar(200) NOT NULL UNIQUE, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Referrals (id uniqueidentifier PRIMARY KEY, userId uniqueidentifier NOT NULL REFERENCES Users(id), code nvarchar(50) NOT NULL UNIQUE, createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE ReferralAttributions (orderId uniqueidentifier PRIMARY KEY REFERENCES Orders(id), referralId uniqueidentifier NOT NULL REFERENCES Referrals(id), buyerHash char(64) NOT NULL UNIQUE, state nvarchar(20) NOT NULL DEFAULT 'pending');
CREATE TABLE AnalyticsEvents (id uniqueidentifier PRIMARY KEY, sessionHash char(64) NOT NULL, kind nvarchar(40) NOT NULL, vendorId uniqueidentifier REFERENCES Vendors(id), createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Settings ([key] nvarchar(100) PRIMARY KEY, data nvarchar(max) NOT NULL);
CREATE INDEX IX_Products_Vendor_Status ON Products(vendorId,status,createdAt);
CREATE INDEX IX_VendorOrders_Vendor ON VendorOrders(vendorId,orderId);
CREATE INDEX IX_Orders_Created ON Orders(createdAt,paymentState);
CREATE INDEX IX_Reservations_Expiry ON InventoryReservations(state,expiresAt);
CREATE INDEX IX_Ledger_Vendor_Currency ON LedgerEntries(vendorId,currency,createdAt);
CREATE INDEX IX_Outbox_State ON OutboxMessages(state,nextAttemptAt);
CREATE INDEX IX_Webhooks_State ON WebhookEvents(state,nextAttemptAt);
INSERT INTO SchemaMigrations(version) VALUES(1);
END;

COMMIT TRANSACTION;
